import { Readable } from 'node:stream';
import { parse } from 'csv-parse';
export async function readCsvRows(text) {
  const parser = Readable.from([text]).pipe(parse({ bom: true, skip_empty_lines: true, record_delimiter: ['\r\n', '\n', '\r'] }));
  const rows = [];
  for await (const row of parser) rows.push(row);
  return rows;
}

